namespace {
int checks=0;
void require(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
bool close(double a,double b,double tolerance=1e-6){return std::abs(a-b)<tolerance;}
hyperion::flight::Game arena(){hyperion::flight::Game f;f.valid=true;f.docked=false;f.planets.push_back({"Test","",{10000,0,0},500,3,{0,1,0}});f.ports.push_back({"Relay","",{5000,5000,5000},{0,1,0},-1,"relay:test","",0});f.ship.gear=false;f.orient({0,0,-1},{0,1,0});return f;}
hyperion::flight::Traffic enemy(V3 at,int role=0){hyperion::flight::Traffic t;t.kind=1;t.id="enemy:"+std::to_string(role);t.role=role;t.home=0;t.position=t.previous=at;t.forward={0,0,1};t.positioned=true;t.health=hyperion::flight::enemyDef(role).hull;t.shield=hyperion::flight::enemyDef(role).shield;t.fireClock=100;t.countermeasures=0;return t;}
hyperion::flight::Bolt projectile(V3 at,V3 velocity,int weapon=0){hyperion::flight::Bolt b{at,at,velocity,2,false};b.weapon=weapon;b.damage=hyperion::flight::weaponDef(weapon).damage;b.owner="NOMA";return b;}
int hostile(const hyperion::flight::Game& f){int count=0;for(const auto& b:f.bolts)if(b.hostile)count++;return count;}
}
int main(){try{
 // Analytic intercept solutions agree with the physical relative trajectory.
 {double t=hyperion::flight::interceptTime({100,0,0},{0,30,0},100);require(t>1&&close(hyperion::flight::length(V3{100,0,0}+V3{0,30,0}*t),100*t),"lead solves a crossing target's interception");require(hyperion::flight::interceptTime({100,0,0},{120,0,0},100)==0,"a faster receding target has no false intercept");require(close(hyperion::flight::interceptTime({100,0,0},{-100,0,0},100),.5),"equal-speed linear case is solved");require(hyperion::flight::interceptTime({}, {},100)==0,"coincident target has a finite zero lead");}
 // A distinct fourth primary keeps the seeker on its own secondary mount.
 {auto f=arena();require(hyperion::flight::primaryWeapon(3)==hyperion::flight::Resonance&&f.selectWeapon(hyperion::flight::Resonance),"fourth key selects resonance");require(!f.selectWeapon(hyperion::flight::Seeker),"seeker cannot become a primary weapon");f.fireClock=0;hyperion::flight::Input input;input.fire=true;f.update(0,input);require(f.bolts.size()==1&&f.bolts[0].weapon==hyperion::flight::Resonance,"resonance produces its own projectile");require(f.ship.combat.energy<100&&f.ship.combat.heat>0&&f.ship.combat.rounds==300,"resonance spends power and heat rather than rounds");double x=f.bolts[0].position.x;f.fireClock=0;f.update(0,input);require(f.ship.combat.shots==2&&x*f.bolts[1].position.x<0,"primaries alternate real muzzle positions");}
 // The port refuge cannot be used as an invulnerable firing position.
 {auto f=arena();f.ports[0].position={};f.ports[0].settlement="staffed";f.lock=1;hyperion::flight::Input input;input.fire=input.missile=true;f.update(0,input);require(f.bolts.empty()&&f.ship.combat.missiles==6&&f.ship.combat.energy==100,"staffed port protection also safes player weapons");}
 // Actual projectile hits conduct to at most two distinct nearby hostiles.
 {auto f=arena();for(int i=0;i<4;i++){auto t=enemy({double(i*40),0,-300});t.id="chain:"+std::to_string(i);f.traffic.push_back(t);}auto civilian=enemy({10,0,-300});civilian.kind=2;civilian.id="civilian";f.traffic.push_back(civilian);f.bolts.push_back(projectile(f.traffic[0].position,{},hyperion::flight::Resonance));f.update(0);
  require(f.traffic[0].energy<100&&f.traffic[1].energy<100&&f.traffic[2].energy<100,"resonance drains the primary contact and two relay targets");require(f.traffic[3].energy==100,"conduction has a two-hop population bound");require(f.traffic[4].health==100&&f.traffic[4].energy==100,"conduction never jumps to civilian traffic");require(std::count_if(f.effects.begin(),f.effects.end(),[](const auto& e){return e.kind==4;})==2,"two conduction hops create two explicit beam endpoints");require(f.traffic[0].shield<f.traffic[1].shield&&f.traffic[1].shield<f.traffic[2].shield,"each hop loses damage");
  f=arena();f.planets[0].centre={40,0,-300};f.planets[0].radius=10;f.traffic={enemy({0,0,-300}),enemy({80,0,-300})};f.traffic[1].id="occluded";f.chainArc(0,14);require(f.traffic[1].energy==100,"terrain blocks a conduction hop");
  f=arena();double energy=f.ship.combat.energy;f.damageShip(14,hyperion::flight::Resonance,{0,0,-100});require(f.ship.combat.energy<energy&&f.ship.combat.shieldDelay==6,"enemy resonance drains player capacitor and delays shields");require(f.damageCue>0&&hyperion::flight::dot(f.hitDirection,f.ship.forward)>.9,"damage stores a directional cockpit cue");
 }
 // Subsystem selection trades hull damage for a precise disabling effect.
 {auto normal=arena(),focused=arena();auto t=enemy({0,0,-300},2);t.shield=0;normal.traffic={t};focused.traffic={t};normal.damageTraffic(0,25,hyperion::flight::Kinetic,t.position+t.forward*10,true);focused.damageTraffic(0,25,hyperion::flight::Kinetic,t.position+t.forward*10,true,1);
  require(focused.traffic[0].modules[0]<100&&focused.traffic[0].modules[1]==100,"drive focus damages only the selected enemy system");require(normal.traffic[0].modules[0]==100&&normal.traffic[0].modules[1]<100,"unfocused nose hits damage forward equipment");require(focused.traffic[0].health>normal.traffic[0].health,"precision focus sacrifices hull damage");
  auto protectedTarget=arena();t.shield=100;protectedTarget.traffic={t};protectedTarget.damageTraffic(0,10,hyperion::flight::Kinetic,t.position,true,1);require(protectedTarget.traffic[0].modules[0]==100,"intact shields protect systems from focused damage");
  auto f=arena();f.traffic={enemy({0,0,-300})};f.combatTarget=f.traffic[0].id;f.aimSystem=2;f.lock=1;hyperion::flight::Input input;input.fire=true;f.update(0,input);require(f.bolts[0].module==2&&f.bolts[0].target==f.combatTarget,"a sustained lock records focus on the actual shot");f.lock=0;f.fireClock=0;f.update(0,input);require(f.bolts[1].module==0,"unlocked shots cannot claim a precision hit");
  f=arena();f.traffic={enemy({0,0,-300},2)};f.traffic[0].modules[2]=20;f.update(0);require(f.traffic[0].shield<=hyperion::flight::enemyDef(2).shield*.2,"disabled enemy shield equipment lowers actual capacity");
  auto healthy=arena(),crippled=arena();healthy.traffic={enemy({0,0,-300},1)};crippled.traffic=healthy.traffic;crippled.traffic[0].modules[0]=0;for(int i=0;i<20;i++){healthy.update(.05);crippled.update(.05);}require(hyperion::flight::length(healthy.traffic[0].velocity)>hyperion::flight::length(crippled.traffic[0].velocity)*2,"enemy drive damage reduces physical movement");
  f=arena();f.traffic={enemy({0,0,-300})};f.traffic[0].modules[1]=0;f.traffic[0].fireClock=0;for(int i=0;i<20;i++)f.update(.05);require(hostile(f)==0&&f.traffic[0].state==4,"destroyed weapon equipment forces withdrawal");
 }
 // Heavy attacks are telegraphed; power, heat and magazines constrain the AI.
 {auto f=arena();auto t=enemy({0,0,-360},2);t.fireClock=0;f.traffic={t};f.update(.05);require(f.traffic[0].charge>0&&f.traffic[0].chargeWeapon==hyperion::flight::Seeker&&hostile(f)==0,"marauder charges a visible seeker before firing");for(int i=0;i<22;i++)f.update(.05);require(f.traffic[0].missiles==1&&f.traffic[0].salvos==1,"charged launch consumes a finite enemy seeker");
  f=arena();t=enemy({0,0,-250},2);t.fireClock=0;t.missiles=0;t.energy=0;f.traffic={t};f.update(.05);require(hostile(f)==0&&f.traffic[0].charge==0,"empty capacitor cannot start a plasma attack");
  f=arena();t=enemy({0,0,-250},1);t.fireClock=0;t.ammunition=0;f.traffic={t};f.update(.05);require(hostile(f)==0&&f.traffic[0].state==4,"empty kinetic magazine forces withdrawal");
  f=arena();t=enemy({0,0,-250},2);t.fireClock=0;t.heat=99;f.traffic={t};f.update(.05);require(f.traffic[0].state==6&&hostile(f)==0,"overheated marauder vents instead of firing");
  f=arena();t=enemy({0,0,-250},3);t.fireClock=0;f.traffic={t};for(int i=0;i<25;i++)f.update(.05);require(f.traffic[0].salvos>0&&f.ship.shield<100,"new disruptor actually fires and damages the player");
 }
 // Sustained heavy fire reaches the heat limit during ordinary AI play.
 {auto f=arena();auto t=enemy({0,0,-400},2);t.fireClock=0;t.missiles=0;f.traffic={t};bool vented=false;
  for(int i=0;i<900;i++){f.ship.shield=100;f.ship.hull=100;f.update(.05);vented|=f.traffic[0].venting;}
  require(vented&&f.traffic[0].salvos>5,"sustained plasma fire naturally creates a venting opportunity");}
 // A saved partial charge must still obey an empty secondary magazine.
 {auto f=arena();auto t=enemy({0,0,-300},2);t.fireClock=0;t.charge=.99;t.chargeWeapon=hyperion::flight::Seeker;t.missiles=0;f.traffic={t};f.update(.05);require(f.traffic[0].missiles==0&&hostile(f)==0,"charged empty enemy mount cannot create a negative missile count");}
 // Evasion uses lateral thrust while the nose tracks the victim.
 {auto f=arena();f.traffic={enemy({0,0,-300},1)};f.bolts.push_back(projectile({0,0,-100},{0,0,-1000}));f.update(.05);const auto& t=f.traffic[0];require(t.state==5&&t.evadeClock>0,"interceptor detects a projectile on a collision course");require(std::abs(t.velocity.x)>1&&std::abs(hyperion::flight::dot(t.forward,hyperion::flight::unit(t.velocity)))<.8,"evasive lateral movement is independent of nose tracking");
 }
 // Enemy countermeasures are finite, cooldown gated and do not create ammunition.
 {auto f=arena();auto t=enemy({0,0,-350});t.countermeasures=2;f.traffic={t};auto incoming=[&](){auto b=projectile(f.traffic[0].position+V3{0,0,150},{0,0,-320},hyperion::flight::Seeker);b.target=f.traffic[0].id;f.bolts.push_back(b);};incoming();f.update(0);require(f.traffic[0].countermeasures==1&&f.bolts.back().target.empty(),"enemy decoy spends stock and defeats seeker guidance");incoming();f.update(0);require(f.traffic[0].countermeasures==1&&!f.bolts.back().target.empty(),"enemy countermeasure cooldown prevents repeated instant use");f.traffic[0].decoyClock=0;f.update(0);require(f.traffic[0].countermeasures==0&&f.bolts.back().target.empty(),"second charge can be expended");incoming();f.traffic[0].decoyClock=0;f.update(0);require(!f.bolts.back().target.empty(),"exhausted enemy decoys cannot break a third lock");}
 // The home workshop consumes actual stocks, and rejects remote/dead references.
 {hyperion::Game g;g.enterFlight();auto& f=g.s.flight;int home=-1;for(int i=0;i<int(f.ports.size());i++)if(auto* p=hyperion::findSettlement(g.s.economy,f.ports[i].settlement))if(p->owner==1&&f.ports[i].planet<0){home=i;break;}require(home>=0,"hostile faction has a real home workshop");auto* port=hyperion::findSettlement(g.s.economy,f.ports[home].settlement);port->stock[hyperion::Alloy]=port->stock[hyperion::Components]=100;auto t=enemy(f.ports[home].position+f.ports[home].normal*110,1);t.home=home;t.faction=1;t.id=f.ports[home].id+":pirate:1";t.health=12;t.modules={60,50,40};t.ammunition=t.missiles=t.countermeasures=0;t.serviceClock=7.95;f.traffic={t};auto credits=g.s.economy.credits;g.updateFlight(.1);
  require(f.traffic[0].ammunition==180&&f.traffic[0].missiles==2&&f.traffic[0].countermeasures==2,"stationary home service replenishes magazines from materials");require(f.traffic[0].health==hyperion::flight::enemyDef(1).hull&&f.traffic[0].modules==std::array<double,3>{100,100,100},"home service repairs hull and equipment");require(port->stock[hyperion::Alloy]<100&&port->stock[hyperion::Components]<100&&g.s.economy.credits==credits,"NPC service consumes real local materials without touching player money");
  port->stock[hyperion::Alloy]=port->stock[hyperion::Components]=0;f.traffic[0]=t;f.events.push_back({"rearmEnemy",home,1,t.id});g.processFlightEvents();require(f.traffic[0].ammunition==0&&f.traffic[0].health==12,"empty port cannot invent enemy ammunition or repairs");
  port->stock[hyperion::Alloy]=port->stock[hyperion::Components]=100;f.traffic[0].position=f.ports[home].position+V3{3000,0,0};auto stock=port->stock;f.events.push_back({"rearmEnemy",home,1,t.id});g.processFlightEvents();require(port->stock==stock&&f.traffic[0].ammunition==0,"remote home-service request cannot transfer stock");f.traffic[0]=t;f.traffic[0].dead=true;f.events.push_back({"rearmEnemy",home,1,t.id});g.processFlightEvents();require(port->stock==stock,"dead ship cannot claim workshop supplies");
 }
 // New tactical state persists, rejects malformed imports, and migrates 3.24 fields.
 {hyperion::Game g;g.enterFlight();g.system("HOME");auto& f=g.s.flight;f.aimSystem=3;f.ship.combat.weapon=hyperion::flight::Resonance;f.ship.combat.shots=91;auto& t=f.traffic[0];t.modules={20,30,40};t.energy=23;t.heat=61;t.charge=.4;t.chargeWeapon=hyperion::flight::Plasma;t.ammunition=17;t.missiles=1;t.countermeasures=0;t.evadeClock=.6;t.serviceClock=3;t.salvos=7;t.venting=true;t.state=5;auto b=projectile(f.ship.position+V3{0,300,0},{100,0,0},hyperion::flight::Resonance);b.module=3;b.target=t.id;f.bolts={b};
  auto path=(std::filesystem::temp_directory_path()/"hyperion-tactics-test.json").string();std::string error;require(hyperion::saveState(g.s,path,error),"tactical save writes");hyperion::Game restored;require(hyperion::loadState(restored.s,path,error),"tactical save restores");const auto& r=restored.s.flight;require(r.aimSystem==3&&r.ship.combat.weapon==hyperion::flight::Resonance&&r.ship.combat.shots==91&&r.bolts[0].module==3,"resonance, focus, shot serial and in-flight focus survive");require(r.traffic[0].modules==t.modules&&r.traffic[0].ammunition==17&&r.traffic[0].countermeasures==0&&r.traffic[0].charge==.4&&r.traffic[0].venting,"enemy equipment, empty decoys and charge survive");
  nlohmann::json valid;{std::ifstream in(path);in>>valid;}auto j=valid;auto write=[&](){std::ofstream out(path);out<<j;};j["flight"]["traffic"][0]["tactics"]["rounds"]=181;write();require(!hyperion::loadState(restored.s,path,error)&&restored.s.flight.aimSystem==3,"oversized enemy magazine is rejected transactionally");j=valid;j["flight"]["traffic"][0]["tactics"]["systems"][0]=-1;write();require(!hyperion::loadState(restored.s,path,error),"negative enemy module is rejected");j=valid;j["flight"]["aimSystem"]=1.5;write();require(!hyperion::loadState(restored.s,path,error),"fractional focus is rejected");j=valid;j["flight"]["combat"]["weapon"]=3;write();require(!hyperion::loadState(restored.s,path,error),"saved seeker cannot occupy a primary slot");
  j=valid;j["flight"].erase("combatRevision");j["flight"].erase("aimSystem");j["flight"]["combat"].erase("shots");j["flight"]["combat"]["weapon"]=2;for(auto& item:j["flight"]["traffic"])item.erase("tactics");j["flight"]["bolts"][0]["weapon"]=0;j["flight"]["bolts"][0].erase("module");write();require(hyperion::loadState(restored.s,path,error),"3.24 combat payload loads without tactical extensions");require(restored.s.flight.aimSystem==0&&restored.s.flight.traffic[0].modules==std::array<double,3>{100,100,100}&&restored.s.flight.traffic[0].ammunition==180,"older ships receive safe tactical defaults");std::filesystem::remove(path);
  auto frozen=hyperion::encodeFlight(g.s.flight,g.s.economy);int turns=g.s.turns;g.action("combatFocus","1");g.action("weapon","4");require(g.s.turns==turns,"new focus and weapon planning actions are free");frozen=hyperion::encodeFlight(g.s.flight,g.s.economy);for(int i=0;i<150;i++)g.simulate(.1);require(hyperion::encodeFlight(g.s.flight,g.s.economy)==frozen,"all tactical timers, NPC ammo and charges freeze between strategy turns");auto time=f.time;g.endTurn();require(f.time>time+54&&g.s.turns==turns+1,"tactical AI resolves on the shared committed turn");
 }
 std::cout<<"Tactics: "<<checks<<" checks passed / resonance, precision, intercepts, enemy systems, charge, heat, evasion, finite defence, workshop economy, persistence and turns\n";return 0;
 }catch(const std::exception& e){std::cerr<<"Tactics failure after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
